<script setup lang="ts">
import {computed} from 'vue';
import {Button,Input,NativeSelect} from '@openclaw-plugins/control-ui-kit';
import {type ManagedTask,type ScheduleDraft,type ScheduleFields,deliveryLabels} from './schedule-model';
const props=defineProps<{source?:ManagedTask;sources:ManagedTask[];creating:boolean;draft:ScheduleDraft;writable:boolean;busy:boolean;safe:(v:unknown)=>string;groupName:(task:ManagedTask)=>string}>();
const emit=defineEmits<{source:[id:string];submit:[fields:ScheduleFields]}>();
const disabled=computed(()=>props.busy||!props.writable),system=computed(()=>props.source?.kind==='repository-sync'&&!props.creating);
const cron=computed(()=>props.draft.kind==='cron');
function submit(){if(!props.source||disabled.value)return;emit('submit',system.value?{time:props.draft.daily,timeZone:props.draft.tz.trim()}:{name:props.draft.name.trim(),...(!props.creating&&props.draft.task!==props.source.task?{task:props.draft.task}:{}),deliveryMode:props.draft.delivery,...(cron.value?{expr:props.draft.mode==='daily'?`${Number(props.draft.daily.split(':')[1])} ${Number(props.draft.daily.split(':')[0])} * * *`:props.draft.expr.trim(),timeZone:props.draft.tz.trim()}:{at:props.draft.at.trim()})});}
const saveDisabled=computed(()=>disabled.value||!props.source?.sourceValid||props.source.busy||(!props.creating&&!['enabled','paused',...(!system.value?['completed']:[])].includes(props.source.status)));
</script>
<template><form class="ar-schedule-form" @submit.prevent="submit"><template v-if="system&&source"><p class="ar-muted">同步范围固定为当前 Agent 及全部登记项目。每日只尝试一次，手动执行也遵守今日去重。</p><p v-if="source.alreadyAttempted" class="ar-warning">今日已有尝试记录；请查看执行记录，今天不会重复同步。</p><p>{{safe(source.constraints)}}</p><label>每日执行时间<Input v-model="draft.daily" aria-label="每日执行时间" type="time" required :disabled="disabled"/></label><label>时区<Input v-model="draft.tz" aria-label="时区" required :disabled="disabled"/></label></template><template v-else><p class="ar-muted">原请求人、群、项目和授权范围继承自已保存的有效群请求。任务正文可在原授权范围内调整。</p><label v-if="creating">来源群请求<NativeSelect :model-value="source?.id??''" aria-label="来源群请求" @update:model-value="emit('source',String($event))"><option v-for="task in sources" :key="task.id" :value="task.id">{{safe(task.name+' · '+task.requester+' · '+groupName(task))}}</option></NativeSelect></label><p v-if="!source">暂无有效的已保存群请求。请先由真人在群里向 Main 创建计划。</p><template v-else><p>{{safe('来源群：'+groupName(source)+' · 原请求人：'+source.requester+' · 项目：'+source.projectId)}}</p><details><summary>查看任务内容与授权范围</summary><p>{{safe('群 ID：'+source.chatId)}}</p><pre class="ar-schedule-task">{{safe(source.task)}}</pre><pre class="ar-schedule-task">{{safe(source.constraints)}}</pre></details><label v-if="!creating" class="ar-schedule-body">任务正文<textarea v-model="draft.task" aria-label="任务正文" rows="8" maxlength="4000" required :disabled="disabled||source.busy||!source.sourceValid"/><span class="ar-muted">仅影响后续触发，须遵守上方原授权范围。</span></label><label>任务名称<Input v-model="draft.name" aria-label="任务名称" required :disabled="disabled"/></label><label>投递位置<NativeSelect v-model="draft.delivery" aria-label="投递位置" :disabled="disabled"><option v-for="(label,value) in deliveryLabels" :key="value" :value="value" :disabled="value==='thread'&&!source.delivery?.canUseThread">{{label}}</option></NativeSelect></label><p class="ar-muted">只影响后续触发，保留原群、请求人、任务范围和正在执行任务的投递快照。</p><label>计划类型<NativeSelect v-model="draft.kind" aria-label="计划类型" :disabled="disabled"><option value="cron">周期计划</option><option value="at">一次性计划</option></NativeSelect></label><label :hidden="!cron">重复方式<NativeSelect v-model="draft.mode" aria-label="重复方式" :disabled="disabled"><option value="daily">每天</option><option value="custom">自定义 Cron</option></NativeSelect></label><label :hidden="!cron||draft.mode!=='daily'">每日执行时间<Input v-model="draft.daily" aria-label="每日执行时间" type="time" :required="cron&&draft.mode==='daily'" :disabled="disabled"/></label><label :hidden="!cron||draft.mode!=='custom'">Cron（五字段）<Input v-model="draft.expr" aria-label="Cron（五字段）" :required="cron&&draft.mode==='custom'" :disabled="disabled"/></label><label :hidden="!cron">时区<Input v-model="draft.tz" aria-label="时区" :required="cron" :disabled="disabled"/></label><label :hidden="cron">执行时间（含时区）<Input v-model="draft.at" aria-label="执行时间（含时区）" placeholder="2026-10-23T09:00:00+08:00" :required="!cron" :disabled="disabled"/></label><p class="ar-schedule-preview">{{cron?(draft.mode==='daily'?`每天 ${draft.daily} · ${draft.tz}`:`Cron · ${draft.expr} · ${draft.tz}`):`一次性 · ${draft.at||'请选择带时区的执行时间'}`}}</p></template></template><footer v-if="source" class="ar-schedule-footer"><span class="ar-muted">修改仅在确认保存后生效；新建计划默认暂停。</span><Button type="submit" :disabled="saveDisabled">{{creating?'创建暂停的任务':'保存设置'}}</Button></footer></form></template>
